def solve(grid, start, goal):
    def valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if valid(nx, ny):
                yield nx, ny

    q, seen = [(start, [start])], set()
    while q:
        (x, y), path = q.pop(0)
        if (x, y) == goal:
            return path
        if (x, y) in seen:
            continue
        seen.add((x, y))
        for nx, ny in neighbors(x, y):
            q.append(((nx, ny), path + [(nx, ny)]))

    return []
