def Solve(grid, start, goal):
    def isValid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] != '#'

    def isNeighbour(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2) == 1

    def dfs(current, path):
        if current == goal:
            return path + [current]
        r, c = current
        neighbours = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
        for nr, nc in neighbours:
            if isValid(nr, nc) and isNeighbour(r, c, nr, nc) and (nr, nc) not in path:
                new_path = dfs((nr, nc), path + [current])
                if new_path:
                    return new_path
        return None

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    elif grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    elif not isValid(start[0], start[1]) or not isValid(goal[0], goal[1]):
        return []

    path = dfs(start, [])
    if path and path[-1] == goal and all(grid[r][c] == '.' for r, c in path):
        return path
    return []
