def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(point):
        return 0 <= point[0] < len(grid) and 0 <= point[1] < len(grid[0]) and grid[point[0]][point[1]] == '.'

    def DFS(current_path, current_point):
        if current_point == goal:
            return [current_path + [current_point]]
        if current_point in current_path:
            return []
        new_paths = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor = (current_point[0] + dx, current_point[1] + dy)
            if is_valid(neighbor):
                new_paths += DFS(current_path + [current_point], neighbor)
        return new_paths

    return DFS([], start)

