def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        return []
    if grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    rows, cols = len(grid), len(grid[0])

    neighbours = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    queue = [(start, [start], set())]
    visited = set()

    while queue:
        (row, col), path, dead_end = queue.pop(0)
        if (row, col) in visited and dead_end:
            continue
        elif (row, col) == goal:
            return path

        for new_row, new_col in neighbours:
            new_row, new_col = row + new_row, col + new_col
            if is_valid(new_row, new_col) and (new_row, new_col) not in visited:
                queue.append(((new_row, new_col), path + [(new_row, new_col)], set()))
                visited.add((new_row, new_col))

        queue.append(((row, col), path, visited | {(row + new_row, col + new_col) for new_row, new_col in neighbours}))
    return []
