def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbours(row, col):
        neighbours = []
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                neighbours.append((r, c))
        return neighbours

    def dfs(row, col, path):
        if (row, col) == goal:
            return [path]
        for nr, nc in get_neighbours(row, col):
            new_path = path + [(nr, nc)]
            result = dfs(nr, nc, new_path)
            if result:
                return result
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    return dfs(start[0], start[1], [start])
