def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    start, goal = tuple(int(c) for c in (start, goal))

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def neighbors(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            yield (r + dr, c + dc)

    def is_valid_path(path):
        prev = None
        for r, c in path:
            if not in_bounds(r, c) or grid[r][c] == '#':
                return False
            if prev is not None and (r, c) not in neighbors(*prev):
                return False
            prev = r, c
        return True

    path = []
    queue = [(start, [start])]
    visited = {start}

    while queue:
        (r, c), path = queue.pop(0)
        if (r, c) == goal:
            return path
        for r, c in neighbors(r, c):
            if r, c not in visited and is_valid(r, c):
                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))
    return []
