def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    rows, cols = len(grid), len(grid[0])
    parents = [[None] * cols for _ in range(rows)]
    queue = deque([start])

    while queue:
        cell = queue.popleft()
        if cell == goal:
            path = []
            while cell is not None:
                path.append(cell)
                cell = parents[cell[0]][cell[1]]
            return path[::-1]

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            row, col = cell[0] + dr, cell[1] + dc
            if 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and parents[row][col] is None:
                queue.append((row, col))
                parents[row][col] = cell

    return []
