def solve(grid, start, goal):
    visited = []

    def fill_path(current, path):
        path.append(current)
        visited.append(current)
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(grid, r, c) and r, c not in visited:
