    # Helper function to check if a position is within the grid
    def is_valid(position):
        row, col = position
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    # Helper function to get the neighbours of a position
    def get_neighbours(position):
        row, col = position
        neighbours = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if is_valid((r, c)):
                neighbours.append((r, c))
        return neighbours

    # DFS visitor
    def dfs(position, path):
        if position == goal:
            return path + [position]
        for neighbour in get_neighbours(position):
            cell = grid[neighbour[0]][neighbour[1]]
            if cell == '.' and neighbour not in path:
                result = dfs(neighbour, path + [position])
                if result:
                    return result
        return None

    # BFS visitor
    def bfs():
        queue = deque([(start, [start])])
        visited = set(start)
        while queue:
            position, path = queue.popleft()
            if position == goal:
                return path
            for neighbour in get_neighbours(position):
                cell = grid[neighbour[0]][neighbour[1]]
                if cell == '.' and neighbour not in visited:
                    queue.append((neighbour, path + [position]))
                    visited.add(neighbour)
        return None

    # Check if start or goal is a wall
    cell = grid[start[0]][start[1]]
    if cell == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Check if start equals goal
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    # Try DFS first
    result = dfs(start, [])
    if result:
        return result
    else:
        # If DFS did not find a path, try BFS
        return bfs()
