import random

def get_neighbors(grid, cell):
    rows, cols = len(grid), len(grid[0])
    neighbors = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        r, c = cell[0] + dr, cell[1] + dc
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            neighbors.append((r, c))
    return neighbors

def dfs(grid, path, visited, start, goal):
    # start DFS from any of the start cell's neighbors
    cell = path[-1]
    if cell in visited:
        return path
    visited.add(cell)
    if cell == goal:
        path.append(cell)
        return path
    for neighbor in get_neighbors(grid, cell):
        if neighbor not in visited:
            path.append(neighbor)
            path = dfs(grid, path, visited, start, goal)
            if path:
                return path
    path.pop()
    visited.remove(cell)
    return []

def solve(grid, start, goal):
    if start[0] == start[1] == goal[0] == goal[1] and grid[start[0]][start[1]] == '.':
        return [start]
    for _ in range(10000): # limit of 10,000 attempts
        path = [start]
        visited = {start}
        path = dfs(grid, path, visited, start, goal)
        if path and path[-1] == goal and all(
            grid[r][c] == '.' for r, c in path
        ):
            # check if the solution was found by backtracking,
            # not by exploring a path that happens to end in the goal cell
            if not path[1:-1] == path[-1]:
                return path
    return []
