        x2, y2 = cell2
        dx = abs(x1 - x2)
        dy = abs(y1 - y2)
        return dx <= 1 and dy <= 1

    def valid_path(path):
        return all(cell in seen for cell in path[1:-1]) and all(grid[cell[0]][cell[1]] == '.' for cell in path)

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

