    seen = {start}

    while open_list:
        cell = open_list.pop(0)
        if cell == goal:
            # Find a valid path by sortof searching back through open_list
            for length in range(2, len(open_list)+1):
                for path in itertools.product(open_list, repeat=length):
                    p = list(path)
                    if p[-1] == cell and cell == goal:
                        if valid_path(p):
                            return p

        neighbours = get_neighbours(cell)

        for neighbour in neighbours:
            open_list.append(neighbour)
            seen.add(neighbour)

    return []
