from collections import deque, defaultdict

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []

    matches = {(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == '.'}
    all_neighbors = set()
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == '.':
                all_neighbors.add((i, j))

    def neighbors(coord):
        neighbors = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if (dx, dy) != (0, 0):
                    new_x, new_y = coord[0] + dx, coord[1] + dy
                    if (new_x, new_y) in all_neighbors:
                        neighbors.append((new_x, new_y))
        return neighbors

    queue = deque([start])
    visited = {start}
    distances = defaultdict(int)
    distances[start] = 0
    parents = {}
    while queue:
        coord = queue.popleft()
        for neigh in neighbors(coord):
            if (neigh not in visited and neigh not in parents) or (neigh in visited and distances[neigh] > distances[coord] + 1):
                if neigh == goal:
                    path = []
                    while neigh in parents:
                        path.append(neigh)
                        neigh = parents[neigh]
                    path.append(start)
                    return path[::-1]
                visited.add(neigh)
                distances[neigh] = distances[coord] + 1
                queue.append(neigh)
                parents[neigh] = coord

    return []
