import random

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    max_attempts = 10000
    path = []
    for _ in range(max_attempts):
        visited = set()
        stack = [(start, [start])]
        while stack:
            cell, path = stack.pop()
            if cell == goal:
                return path
            visited.add(cell)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                r, c = cell[0] + dr, cell[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#' and (r, c) not in visited and (r, c) not in path:
                    stack.append(((r, c), path + [(r, c)]))
        # reset for next attempt
        stack.clear()
        path = []

    return []

def all_adjacent_valid(grid, row, col):
    rows, cols = len(grid), len(grid[0])
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = row + dr, col + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
            yield (nr, nc)

def valid_and_not_visited(grid, visited, cell, path):
    if cell not in visited:
        visited.add(cell)
        path.add(cell)
        yield from all_adjacent_valid(grid, cell[0], cell[1])

def random_syntactic_path(grid, start, goal):
    visited = set()
    stack = [start]
    while stack:
        cell = stack.pop()
        for c in valid_and_not_visited(grid, visited, cell, set()):
            if c == goal:
                s = [start]
                while c:
                    next_cell = next((x for x in visited if x not in s), None)
                    s.append(next_cell)
                    s.append(c)
                    c = next_cell
                return s
            else:
                stack.append(c)
        visited.discard(cell)

    return []
