import random

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]

    direction = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    stack = [([start], start)]

    while stack:
        path, current = stack.pop()
        for i in range(4):
            move = [current[0] + direction[i][0], current[1] + direction[i][1]]
            if (1 <= move[0] <= len(grid) and 
                1 <= move[1] <= len(grid[move[0] - 1]) and 
                grid[move[0] - 1][move[1] - 1] == '.' and 
                move not in path):
                new_path = path + [move]
                if move == goal:
                    good_job = path + [move]
                    return good_job
                stack.append((new_path, move))

    return []

def is_valid(grid, start, goal):
    if start[0] == 0 or start[1] == 0 or start[0] == len(grid) or start[1] == len(grid[0]):
        return False
