    def neighbours(cell: Tuple[int, int]) -> Set[Tuple[int, int]]:
        row, col = cell
        return {(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)}

    def is_goal(cell: Tuple[int, int]) -> bool:
        return cell == goal

    stack: List[Tuple[Tuple[int, int], Tuple[int, int]]] = [(start, start)]
    visited: Set[Tuple[int, int]] = set()
    path: List[Tuple[int, int]] = [start]

    while stack:
        parent, cell = stack.pop()
        if is_goal(cell) and parent != start:
            current = cell
            while current != parent:
                current = path.pop()
                path.append(current)
            return path + [start]

        if cell not in visited and is_valid(cell):
            visited.add(cell)
            for new_cell in neighbours(cell):
                if new_cell not in path:
                    stack.append((cell, new_cell))
                    path.append(new_cell)
                    break

    return []
