from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    rows_out_of_bounds, cols_out_of_bounds, wall, visited = set(), set(), set(), set()

    def is_out_of_bounds(row, col):
        return row < 0 or row >= rows or col < 0 or col >= cols

    def is_wall(row, col):
        return grid[row][col] == '#'

    def get_neighbors(row, col):
        neighbors = [
            (row-1, col) if not is_out_of_bounds(row-1, col) and not is_wall(row-1, col) else None,
            (row+1, col) if not is_out_of_bounds(row+1, col) and not is_wall(row+1, col) else None,
            (row, col-1) if not is_out_of_bounds(row, col-1) and not is_wall(row, col-1) else None,
            (row, col+1) if not is_out_of_bounds(row, col+1) and not is_wall(row, col+1) else None
        ]
        return [n for n in neighbors if n is not None]

    def get_index(row, col):
        return row * cols + col

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                rows_out_of_bounds.add(get_index(r, c))
            elif grid[r][c] == '#':
                rows_out_of_bounds.add(get_index(r, c))
                wall.add(get_index(r, c))

    if start == goal:
        return [start]

    if is_wall(start[0], start[1]) or is_wall(goal[0], goal[1]):
        return []

    visited.add(get_index(start[0], start[1]))
    queue = deque([(start, [start])])

    while queue:
        (cur, path) = queue.popleft()

        if cur == goal:
            return path

        for neighbor in get_neighbors(cur[0], cur[1]):
            if get_index(neighbor[0], neighbor[1]) not in visited:
                visited.add(get_index(neighbor[0], neighbor[1]))
                queue.append((neighbor, path + [neighbor]))

    return []
