        for dx in range(-1, 2):
            for dy in range(-1, 2):
                if (dx, dy) == (0, 0):
                    continue
                nx, ny = x + dx, y + dy
                if (0 <= nx < len(grid)) and (0 <= ny < len(grid[0])) and (grid[nx][ny] == '.'):
                    yield (nx, ny)

