```python
import random
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]   # left, right, up, down

    def is_valid(row: int, col: int) -> bool:
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def dfs(row: int, col: int, path: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        path.append((row, col))
        if (row, col) == goal:
            return [path]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if is_valid(nr, nc):
                result = dfs(nr, nc, path)
                if result:
                    return result
                path.pop()
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    grid_copy = [row[:] for row in grid]
    while True:
        random.shuffle(directions)
        for dr, dc in directions:
            rn = start[0] + random.randint(-1, 1) * dr
            cn = start[1] + random.randint(-1, 1) * dc
            if is_valid(rn, cn):
                path = dfs(rn, cn, [])
                if path:
                    for i in range(len(path)):
                        grid_copy[path[i][0]][path[i][1]] = 'x'
                    return [tuple(loc) for loc in path]

def generate_grid(nrows: int, ncols: int) -> List[str]:
    return [["." * ncols] * nrows]
