def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal:
        return [start]
    if any(cell in '#.' for cell in grid[start[0]] + grid[start[1]]):
        return []

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    queue = deque([start])
    paths = {start: [start]}

    while queue:
        (row, col), path = queue.popleft(), paths[(row, col)]
        if (row, col) == goal:
            return [start] + path + [goal]

        for dr, dc in directions:
            n_row, n_col = row + dr, col + dc
            if is_valid(n_row, n_col) and (n_row, n_col) not in paths:
                queue.append((n_row, n_col))
                paths[(n_row, n_col)] = path + [(n_row, n_col)]

