        if start == tuple(goal_target):
            return list(path + [goal_target])

        path = path + [goal_target]
        visited.add(tuple(goal_target))

        for move in valid_moves(grid, goal_target[0], goal_target[1]):
            if tuple(move) not in visited:
                heapq.heappush(queue, (max(len(path) + 1, 0), move, path))

