def solve(grid, start, goal):
    # Helper function to check if a cell is valid
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    # Helper function to apply a random move to the path
    def random_move(path):
        if not path:
            return [(random.randint(0, len(grid) - 1), random.randint(0, len(grid[0]) - 1))]
        else:
            directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]
            random.shuffle(directions)
            for dr, dc in directions:
                new_row, new_col = path[-1][0] + dr, path[-1][1] + dc
                if is_valid(new_row, new_col):
                    return path + [(new_row, new_col)]
        return [start]

    # Helper function to check if a path is valid
    def check_path(path):
        for s in range(1, len(path)):
            row, col = path[s-1]
            new_row, new_col = path[s]
            if abs(new_row - row) + abs(new_col - col) != 1:
                return False
            if grid[new_row][new_col] == '#':
                return False
        return True

    # Try random moves until a valid path is found or 100000 attempts have been made
    attempts = 0
    path = [start]
    while attempts < 100000 and check_path(path) is False:
        path = random_move(path)
        attempts += 1

    # If too many attempts have been made, return an empty path
    if attempts == 100000:
        return []

    # If the last cell in the path is the goal, return the path
    if path[-1] == goal:
        return path
    else:
        return []
