import heapq
import copy

def neighbors(cell, rows, cols):
    r, c = cell
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '.':
            yield (r + dr, c + dc)

def heuristic(cell, goal):
    return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

def failed_push(queue):
    return not queue or queue[0][0] < queue[-1][0]

def push(queue, value, priority):
    heapq.heappush(queue, (priority, value))

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    queue = [(0, start)]
    visited = {start: 0}
    came_from = {start: None}
    current_cost = {start: 0}

    while queue:
        cheapest, current = heapq.heappop(queue)
        if current == goal:
            path = []
            while current:
                path.append(current)
                current = came_from[current]
            return path[::-1]

        for neighbor in neighbors(current, len(grid), len(grid[0])):
            if neighbor not in visited or current_cost[current] + 1 < current_cost.get(neighbor, float('inf')):
                priority = current_cost[current] + 1 + heuristic(neighbor, goal)
                push(queue, neighbor, priority)
                visited[neighbor] = 1
                came_from[neighbor] = current
                current_cost[neighbor] = current_cost[current] + 1

        if failed_push(queue):
            del queue[:]

            # Avoid getting stuck in an infinite loop by discarding visited nodes that
            # became unusable due to changed queue order
            for visited_node in copy.deepcopy(visited):
                if visited_node in came_from and current_cost[visited_node] > current_cost[came_from.get(visited_node, visited_node)]:
                    del visited[visited_node]
                    del came_from[visited_node]
                    del current_cost[visited_node]
            continue

    return []
