def solve(grid, start, goal):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up
    rows, cols = len(grid), len(grid[0])
    stack = [(start, [start])]
    visited = {start}

    while stack:
        (x, y), path = stack.pop()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited:
                if (nx, ny) == goal:
                    return path + [(nx, ny)]
                visited.add((nx, ny))
                stack.append(((nx, ny), path + [(nx, ny)]))
    return []

def is_valid(grid, x, y):
    return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

def solve_helper(grid, start, goal, prev):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up
    rows, cols = len(grid), len(grid[0])
    queue = [(start, [start])]
    visited = set([start])

    while queue:
        (x, y), path = queue.pop(0)
        if path[-1] == goal:  # found a path
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(grid, nx, ny) and (nx, ny) not in visited:
                new_path = path + [(nx, ny)]
                if grid[nx][ny] == '.':
                    queue.append(((nx, ny), new_path))
                    visited.add((nx, ny))
                else:
                    queue.append(((nx, ny), prev[(nx, ny)]))
                    prev[(nx, ny)] = new_path

    return []

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':  
        return [start]

    surface = [[False]*len(grid[0]) for _ in range(len(grid))]
    stack = [start]

    length = 1
    while len(stack) > 0:
        popped = stack[-length]
        i = popped[0]
        j = popped[1]

        if 0<= i-1 < len(grid):  #up
            if grid[i-1][j] == '.' and not surface[i-1][j]:
                surface[i-1][j] = True
                stack.append((i-1, j))

        if 0<= j+1 < len(grid[0]):  # right
            if grid[i][j+1] == '.' and not surface[i][j+1]:
                surface[i][j+1] = True
                stack.append((i, j+1))

        if 0<= i+1 < len(grid):  # down
            if grid[i+1][j] == '.' and not surface[i+1][j]:
                surface[i+1][j] = True
                stack.append((i+1, j))

        if 0<= j-1 < len(grid[0]):  # left
            if grid[i][j-1] == '.' and not surface[i][j-1]:
                surface[i][j-1] = True
                stack.append((i, j-1))

        prev = { cell: None for cell in stack }
        return solve_helper(grid, start, goal, prev)

    return []
