import sys

def dijkstra(n, edges, s, t):
    def initialize_dist():
        return [sys.maxsize] * n
    def update_dist(dist, u, d):
        return min(dist[u], d)

    dist = initialize_dist()
    dist[s] = 0
    visited = set()
    for _ in range(n):
        visited_add = False
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                visited_add = True
        if not visited_add:
            break
        visited.add(next(u for u in range(n) if dist[u] != sys.maxsize))
    if next((d for i, d in enumerate(dist) if i != s and d == sys.maxsize), None) == None:
        return dist[t]
    return -1

def solve(n, edges, s, t):
    shortest_path = min(dijkstra(n, e, s, t) for e in [edges, [(v, u, w) for u, v, w in edges]])
    return shortest_path

