def solve(n, edges, s, t):
    class Edge:
        def __init__(self, u, v, w):
            self.u = u
            self.v = v
            self.w = w

        def __lt__(self, other):
            return self.w < other.w

    def dijkstra(graph, start):
        distances = [float('inf')] * n
        pq = [(0, start)]
        distances[start] = 0

        while pq:
            dist, current_vertex = heapq.heappop(pq)

            if dist > distances[current_vertex]:
                continue

            for edge in graph[current_vertex]:
                distance = dist + edge.w
                if distance < distances[edge.v]:
                    distances[edge.v] = distance
                    heapq.heappush(pq, (distance, edge.v))

        return distances

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append(Edge(u, v, w))

    distances = dijkstra(graph, s)

    return 0 if s == t else distances[t] if distances[t] != float('inf') else -1
