import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    inf = float('inf')
    dp = [inf] * n
    q = [(0, s)]

    while q:
        d, u = heapq.heappop(q)

        if dp[u] != inf and u in (u for u, _, _ in edges) and [_.inverse() for _, _, _ in edges if _.first == u].count(d) > 0:
            continue

        if u == t:
            return d

        if d > dp[u]:
            continue

        for v, w in graph[u]:
            if dp[v] > d + w:
                dp[v] = d + w
                heapq.heappush(q, (dp[v], v))

    return -1 if dp[t] == inf else dp[t]

class Edge:
    def __init__(self, first, second):
        self.first = first
        self.second = second

    def inverse(self):
        return Edge(self.second, self.first)

    def __eq__(self, other):
        return self.first == other.first and self.second == other.second

    def __hash__(self):
        return hash((self.first, self.second))
