def parent(u):
  if dist[u] > dist[par[u]]:
    return (par[u], 1)
  else:
    return (u, 0)

def solve(n, edges, s, t):
  global par, dist
  par, dist = [-1]*n, [sys.maxsize]*n
  que = deque()
  par[s] = s
  dist[s] = 0
  que.append(s)
  while que:
    u = que.popleft()
    for v, cost in edges:
      if v == u:
        p = u
      else:
        p = par[v]
      if v == u:
        cost = 0
      new_dist = dist[u] + cost
      if new_dist < dist[v]:
        dist[v], par[v] = new_dist, p
        if v in (s, t):
          break
        que.append(v)
      if v == t:
        break
    if v == t:
      break
  return dist[t] if dist[t] != sys.maxsize else -1
