import heapq

def solve(n, edges, s, t):
    D, P = {i: (float('inf'), 0) for i in range(n)}, {i: None for i in range(n)}
    P[s] = -1
    D[s] = (0, s)
    queue = [(0, s)]

    while queue:
        di, i = heapq.heappop(queue)

        if di == D[i][0]:
            for u, v, w in edges:
                if u == i:
                    if D[v][0] > di + w:
                        D[v] = (di + w, i)
                        P[v] = i
                        heapq.heappush(queue, (di + w, v))

    if D[t][0] == float('inf'):
        return -1
    elif D[t][0] == 0:
        return 0

    path = []
    i = t
    while i is not None:
        path.insert(0, i)
        i = P[i]
    for i in range(len(path) - 1):
        for u, v, w in edges:
            if u == path[i] and v == path[i + 1]:
                return w

    return -1
