import heapq

def dijkstra(n, edges, s, t):
    def construct_graph(edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    def bellman_ford(graph, source):
        dist = [sys.maxsize] * n
        dist[source] = 0

        for _ in range(n - 1):
            for node in range(n):
                for neighbor, weight in graph[node]:
                    if dist[node] + weight < dist[neighbor]:
                        dist[neighbor] = dist[node] + weight

        return dist

    def check_negative_cycle(graph, dist):
        for node in range(n):
            for neighbor, weight in graph[node]:
                if dist[node] + weight < dist[neighbor]:
                    return True
        return False

    graph = construct_graph(edges)
    if s == t:
        return 0
    dist = bellman_ford(graph, s)
    return -1 if dist[t] == sys.maxsize else dist[t]

def solve(n, edges, s, t):
    result = dijkstra(n, edges, s, t)
    return result
