def relax(edges, dist, visited):
    pq = [(0, visited[0])]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]: continue
        for v, w in edges[u]:
            if not visited[v]:
                dist[v] = min(dist[v], dist[u] + w)
                heapq.heappush(pq, (dist[v], v))

def solve(n, edges, s, t):
    dist = [sys.maxsize] * n
    visited = [False] * n
    visited[s] = True
    dist[s] = 0

    for _ in range(n + 1):
        relax(edges, dist, visited)

        if visited[t]:
            return dist[t]
        new_visited = visited[:]
        for i in range(n):
            if not visited[i] and dist[i] != sys.maxsize:
                new_visited[i] = True
                relax(edges, dist, new_visited)
                visited = new_visited

    return -1
