import heapq

def bfs(edges, n, s):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [sys.maxsize] * n
    dist[s] = 0
    q = [(0, s)]

    while q:
        d, u = heapq.heappop(q)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(q, (dist[v], v))

    return dist

def solve(n, edges, s, t):
    dist_s = bfs(edges, n, s)
    dist_t = bfs(edges, n, t)

    if dist_s[t] == -1 or dist_t[s] == -1:
        return -1

    return dist_s[t] + dist_t[s] - 1

def finalize(edges, n, s, t):
    d = solve(n, edges, s, t)
    if d > sys.maxsize // 2:
        d = -1
    return d
