import heapq

def find(u, p):
    if p[u] != u:
        p[u] = find(p[u], p)
    return p[u]

def solve(n, edges, s, t):
    p = list(range(n))
    d = [float('inf')] * n
    d[s] = 0
    q = [(0, s)]
    while q:
        curr_dist, u = heapq.heappop(q)
        if u != s and d[u] < curr_dist:
            continue
        for v, w in edges:
            if v == u:
                pv = find(v, p)
                for i in range(n):
                    if find(i, p) == pv:
                        p[i] = v
                t0, e0  = d[u], (u, v, w)
                while t0 > 0:
                    if d[u] > d[v] + w:
                        d[u] = d[v] + w
                        heapq.heappush(q, (d[u], u))
                    t0 -= 1
                    u, v, w = id(e0), e0[1], e0[2]
                    e0 = (u, v, w)
                if d[v] < curr_dist:
                    q.append((d[v], v))
            elif d[u] + w < d[v]:
                d[v] = d[u] + w
                heapq.heappush(q, (d[v], v))
    return d[t] if d[t] != float('inf') else -1
