import heapq

def solve(n, edges, s, t):
    def bellman_ford():
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] != float('inf') and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                return float('inf') # negative cycle detected
        return dist[t] if dist[t] != float('inf') else -1

    def dijkstra():
        dist = [float('inf')] * n
        dist[s] = 0
        pq = [(0, s)]
        seen = {s}
        while pq:
            d, u = heapq.heappop(pq)
            if u == t:
                return d
            if d > dist[u]:
                continue
            for v, w in get_neighbors(edges, u):
                if v not in seen:
                    seen.add(v)
                    heapq.heappush(pq, (d + w, v))
                    dist[v] = min(dist[v], d + w)
        return -1

    def get_neighbors(edges, u):
        neighbors = []
        for e in edges:
            if e[0] == u:
                neighbors.append((e[1], e[2]))
        return neighbors

    return bellman_ford() if bellman_ford() != -1 else dijkstra()

# Note: if the graph has a negative cycle between s and t, 
# both Bellman-Ford and Dijkstra will return infinity, 
# but negative cycles are only possible if an edge weight 
# is negative and a path from s to t uses that edge
# (Bellman-Ford checks for this; Dijkstra does not)
