import sys
from heapq import heappop, heappush

INF = sys.maxsize

def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [INF] * n
    distance[s] = 0
    pq = [(0, s)]

    while pq:
        dist, nd = heappop(pq)
        if dist > distance[nd]:
            continue
        for nxt, wt in graph[nd]:
            if dist + wt < distance[nxt]:
                distance[nxt] = dist + wt
                heappush(pq, (distance[nxt], nxt))

    return distance[t]

def solve(n, edges, s, t):
    dist_s_to_t = INF
    if s == t:
        return 0
    for i in range(n):
        if i != s:
            dist_s_to_i = dijkstra(n, edges, s, i)
            dist_i_to_t = dijkstra(n, edges, i, t)
            if i != t and dist_s_to_i != INF and dist_i_to_t != INF:
                dist_s_to_t = min(dist_s_to_t, dist_s_to_i + dist_i_to_t)
    return dist_s_to_t if dist_s_to_t != INF else -1
