def solve_dsu(n, edges, s, t):
    parent = list(range(n))
    size = [1] * n

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if size[root_u] < size[root_v]:
                parent[root_u] = root_v
                size[root_v] += size[root_u]
            else:
                parent[root_v] = root_u
                size[root_u] += size[root_v]

    graph = {}
    for u, v, w in edges:
        graph.setdefault(u, []).append((v, w))

    distances = [float('inf')] * n
    distances[s] = 0

    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == t:
            return d
        for v, w in graph.get(u, []):
            if find(u) != find(v):
                union(u, v)
                if d + w < distances[v]:
                    distances[v] = d + w
                    heapq.heappush(pq, (distances[v], v))

    return float('inf')
