    max_dist[s] = 0
    pq = [(0, s, False)]
    distances = [0] * n

    while pq:
        dist, node, relax = heapq.heappop(pq)
        if dist != max_dist[node] and relax:
            continue
        for neighbor, neighbor_dist in graph[node]:
            new_dist = dist + neighbor_dist
            if max_dist[neighbor] <= new_dist:
                max_dist[neighbor] = new_dist
                distances[neighbor] = new_dist - dist
                heapq.heappush(pq, (new_dist, neighbor, True))
            else:
                if new_dist + neighbor_dist * distances[neighbor] >= max_dist[neighbor]:
                    distances[neighbor] = (new_dist - dist) + (max_dist[neighbor] - new_dist) / neighbor_dist
                    max_dist[neighbor] = new_dist + neighbor_dist * distances[neighbor]
                    heapq.heappush(pq, (new_dist, neighbor, False))

