                        if (0, v) not in visited:
                            visited.add((0, v))
                            heapq.heappush(q, (d - w, v, path))
                        elif w > d:
                            if (0, v) not in visited:
                                visited.add((0, v))
                                heapq.heappush(q, (d - w, v, path))
