from collections import deque

def add_vertex(graph, u, v, w):
    graph[u].append((v, w))
    graph.setdefault(v, [])

def topological_sort(s, graph):
    visited = [0]*len(graph)
    stack = [s]
    order = []
    while stack:
        node = stack.pop()
        if visited[node]:
            if node != s and not graph[node]:
                return -1  # cycle detected
        else:
            visited[node] = 1
            stack.extend((v for v, _ in reversed(graph[node])))
            order.append(node)
    return reversed(order)

def instructions(a, b, c, s, pi, d, inf=int('inf')):
    if d[s] < d[c] + a[b][c]:
        d[s] = d[c] + a[b][c]
        pi[s] = c

def bellman_ford(s, weights):
    n = len(weights)
    d = [inf]*n
    pi = [-1]*n
    d[s] = 0
    for _ in range(n):
        for u in range(n):
            for v, w in weights[u]:
                instructions(a=1, b=u, c=v, s=s, pi=pi, d=d, inf=inf)
    for u in range(n):
        for v, w in weights[u]:
            if d[u] + w < d[v]:
                return -1  # negative weight cycle detected
    return d

def negative_cycle(graph):
    weights = [[(v, w) for v, w in u] for u in graph]
    n = len(graph)
    for u in graph:
        add_vertex(graph=graph, u=u, v=u, w=0)
    s = 0
    weights2 = [[(v, w) for v, w in u if v != u] for u in graph]
    d = bellman_ford(s, weights2)
    return d and -1 or max(bellman_ford(s, weights), key=lambda x: graph[x][-1][1])

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        add_vertex(graph, u, v, w)
    d = topological_sort(s, graph)
    if d == -1:
        return -1
    if s == t:
        return 0
    if negative_cycle(graph):
        return -1
    visited = [0] * n
    queue = deque([(s, 0)])
    visited[s] = 1
    while queue:
        u, w = queue.popleft()
        for v, vw in graph[u]:
            if not visited[v]:
                queue.append((v, w + vw))
                visited[v] = 1
                if v == t:
                    return w +vw
    return -1
