from typing import List, Tuple

def get_nodes(edges: List[Tuple[int, int, int]]) -> List[Tuple[int, int]]:
    """Get list of all nodes used in edges"""
    nodes = set()
    for u, v, _ in edges:
        nodes.add(u)
        nodes.add(v)
    return list(nodes)

def get_edge_restrictions(edges: List[Tuple[int, int, int]], nodes: List[int]) -> List[Tuple[int, int, int, int]]:
    """Get list of (u, v, i) tuples for each edge from node i"""
    m = len(nodes)
    edges_restrictions = [[] for _ in range(m)]
    for i, (u, v, _) in enumerate(edges):
        edges_restrictions[u].append((i, v, m))

    for i in range(m):
        edges_restrictitions[i].sort(key=lambda x: x[2])

    for i in range(m - 2, -1, -1):
        for j in range(i + 1, m):
            edges_restrictions[j].append((i, j, i + 1))

    restriction_list = []
    path_nodes = [m] * m
    for i in range(m):
        for index, v, j in edges_restrictions[i]:
            restriction_list.append((i, path_nodes[i], j, index, v))
            path_nodes[j] = min(path_nodes[j], v)

    return restriction_list

def get_min_path_sum(logits: List[int], log_weights: List[bool], nodes_restrictions: List[Tuple[int, int, int, int]]) -> List[int]:
    """Find minimum path sum using topological sorting DAG and Bellman-Ford"""
    vertices = set(range(len(nodes_restrictions)))
    edges = [(u, v) for u, u_log, v, _, _ in nodes_restrictions]
    min_cost_weight = {node: float('inf') for node in vertices}
    min_cost_weight[len(nodes_restrictions)] = 0
    for _ in range(len(nodes_restrictions)):
        for u, u_log, v, i, _ in nodes_restrictions:
            if u_log and u != v and min_cost_weight[v] > min_cost_weight[u] + logits[i]:
                min_cost_weight[v] = min_cost_weight[u] + logits[i]
        if not all(log_weights[i] for i in range(len(logits))):
            break

    for u, _, v, _, _ in nodes_restrictions:
        if min_cost_weight[v] > min_cost_weight[u]:
            return [-1]  # -1 if there is a negative cycle

    return [min_cost_weight[v] for v in vertices]

def solve(n: int, edges: List[Tuple[int, int, int]], s: int, t: int) -> int:
    """Find min-cost path sum from node s to node t in directed graph"""
    nodes = get_nodes(edges)
    nodes_restrictions = get_edge_restrictions(edges, nodes)
    min_cost_weight = get_min_path_sum(nodes_restrictions, [log_weights[i] for i in range(len(nodes_restrictions))], nodes_restrictions)
    return min_cost_weight[s] if s < len(nodes_restrictions) and s >= 0 else (0 if s == t else -1)
