                    min_cost_array[to_block] = cost
                    heapq.heappush(queue, (cost, to_block))
    return min_cost_array[-2] - min_cost_array[-1] + E(block_num - 2, block_num - 1, 0) + E(block_num - 1, s, graph[s][0][0]) if min_cost_array[-1] == float('inf') else min_cost_array[-1]

