            i += 1
        self.l[i], self.l[self.cnt - 1] = self.l[self.cnt - 1], self.l[i]
        self.cnt -= 1
        if 2 * i >= self.cnt + MAX_QUEUE_SIZE:
            self.__halve()
            if 2 * i >= self.cnt + MAX_QUEUE_SIZE:
