                    new_dist = curr_dist + weight
                    if new_dist < dist[neighbor]:
                        dist[neighbor] = new_dist
                        prev[neighbor] = curr_node
                        heapq.heappush(pq, (new_dist, neighbor))

        return float('inf'), []

    def get_random_node_dist():
        nodes = [node for node in range(n) if node not in {s, t}]
        return random.choice(nodes)

    random_nodes = [get_random_node_dist() for _ in range(min(200, n + 1))]

    best_dist, _ = find_shortest_path()

    for node in random_nodes:
        if node not in {s, t}:
            edgeset.remove((node, node, 0))
            edgeset.remove((node, node, 100))  # elif not selfloop 
            new_best_dist, _ = find_shortest_path()

            if new_best_dist < best_dist:
                best_dist = new_best_dist

            for edge1 in edgeset:
                if edge1[1] == node:
                    new_dist = new_best_dist
                else:
