    for (u, v, w) in edges:
        deg[u] += 1
    clock = []
    for i in range(n):
        if deg[i] == 1:
            clock.append(i)
    res = []
    while clock:
        i = clock.pop()
        O = graph[i]
        for j, w in O:
            deg[j] -= 1
            if deg[j] == 1:
                clock.append(j)
            elif deg[j] == 0:
                res.extend([j] + [x[0] for x in O if x != (j, w)])
    return res

def relax(u, v, w, dist, vis):
    if dist[v] > dist[u] + w:
        dist[v] = dist[u] + w
        vis.append(v)

def Bellman(graph, s):
    n = len(graph)
    dist = [float('inf')] * n
    dist[s] = 0
    vis = []
    queue = []
    heapq.heappush(queue, (0, s))
    while queue:
        (d, u) = heapq.heappop(queue)
        vis.append(u)
        O = graph[u]
        for v, w in O:
            if v not in vis and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(queue, (dist[v], v))
    return dist, vis

def solve(n, edges, s, t):
