            x, y = queue.popleft()
            if (x, y) == goal:
                path = [(x, y)]
                while (x, y) != start:
                    for dx, dy in directions:
                        if (x+dx, y+dy) in visited and abs((x+dx, y+dy)[0] - x) + abs((x+dx, y+dy)[1] - y) == 1:
