        return [start]

    def is_valid(grid, pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_moves(pos, visited):
        row, col = pos
        moves = []
        for row2, col2 in [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]:
            if is_valid(grid, (row2, col2)) and (row2, col2) not in visited:
                moves.append((row2, col2))
        return moves

    def dfs(pos, path):
        if pos == goal:
            return path + [pos]
