import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [float('inf')] * n
    distance[s] = 0

    pq = [(0, s)]

    while pq:
        curr_distance, curr_node = heapq.heappop(pq)

        if curr_distance > distance[curr_node]:
            # If the popped distance is less than current distance that means distances list has been changed and hence nodes that came after the node at this index in pq will also be removed 
            while pq and distance[pq[0][1]] < pq[0][0]:
                heapq.heappop(pq)

        if curr_node == t:
            return curr_distance

        for neighbor, weight in graph[curr_node]:
            candidate_distance = curr_distance + weight
            if candidate_distance < distance[neighbor]:
                distance[neighbor] = candidate_distance
                heapq.heappush(pq, (candidate_distance, neighbor))

    return -1
