import heapq

def dijkstra(n, edges, s, t):
    def reset_dist():
        dist = [sys.maxsize] * n
        dist[s] = 0
        return dist

    def expand(u, dist):
        heap = [(z, u) for u, z in enumerate(dist) if z < sys.maxsize]
        heapq.heapify(heap)

        visited = set()
        while heap and u not in visited:
            _, u = heapq.heappop(heap)
            visited.add(u)
            for v, w in build_graph(edges):
                if v == u and v not in visited:
                    dist[v] = min(dist[v], dist[u] + w)
                if v != u and dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return visited

    def _solve(s, t):
        dist = reset_dist()
        curr_vertex = t
        for _ in range(n): # slow down by n to finish        
            if curr_vertex in expand(curr_vertex, dist):
                break
            if curr_vertex == s:
                return 0
        return -1 if dist[t] == sys.maxsize else int(dist[t])

    def build_graph(edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    return _solve(s, t)
