import math

def dijkstra(n, edges, s, t):
    # Build adjacency list
    adj_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_list[u].append((v, w))

    # Distance and heap initialization
    dist = [math.inf] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        _dist, u = heappop(heap)
        if dist[u] < _dist:
            # Path reconstruction node takes O(n) in worst case (çok_decode_to eigveve)
            continue
        for v, w in adj_list[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heappush(heap, (dist[v], v))

    return dist[t] if 0 <= t < n else -1


def heappush(heap, item):
    heap.append(item)
    _siftup(heap, len(heap) - 1)


def _siftup(heap, index):
    parent = (index - 1) >> 1
    if index <= 0:
        return
    elif heap[parent] > heap[index]:
        heap[parent], heap[index] = heap[index], heap[parent]
        _siftup(heap, parent)


def heappop(heap):
    if len(heap) == 0:
        raise IndexError('pop from an empty list')
    if len(heap) == 1:
        return heap.pop()
    root = heap[0]
    heap[0] = heap.pop()
    _siftdown(heap, 0, 0)
    return root


def _siftdown(heap, start_pos, pos):
    if pos >= len(heap):
        return
    child_pos = 2 * pos + 1
    exchange_pos = pos
    if child_pos < len(heap):
        if heap[child_pos] < heap[exchange_pos]:
            exchange_pos = child_pos
    if child_pos + 1 < len(heap):
        if heap[child_pos+1] < heap[exchange_pos]:
            exchange_pos = child_pos+1
    if exchange_pos != pos:
        heap[pos], heap[exchange_pos] = heap[exchange_pos], heap[pos]
        _siftdown(heap, start_pos, exchange_pos)
