                return float('inf')
            vis[u[1]] = True
            for v, w in [(u[1], n) for u, v, w in edges if u == u[1]]]:
                if not vis[v] and distance[v] > distance[u[1]] + w:
                    distance[v] = distance[u[1]] + w
