import sys
from collections import deque

def bfs(n, edges, s, t):
    def add_source(s):
        graph[s] = [(iwt, i) for i, wt in edges if i == s]

    def dijkstra(graph, s):
        queue = deque([(0, s)])
        visited = [False] * n
        distances = [sys.maxsize] * n
        distances[s] = 0
        while queue:
            d, u = queue.popleft()
            if visited[u]:
                if d < distances[u]:
                    distances[u] = d
                    queue.append((d, u))
                else:
                    queue.append((d, u))
                visited[u] = True
            for c, v in graph[u]:
                distance = d + c
                if distance < distances[v]:
                    distances[v] = distance
                    queue.append((distance, v))
        return distances, queue

    graph = [[] for _ in range(n)]
    add_source(s)
    for u, v, wt in edges:
        graph[u].append((wt, v))

    _, queue = dijkstra(graph, s)

    while queue:
        _, u = queue.popleft()
        if u == t:
            return queue.index((0, u))

    return -1

def solve(n, edges, s, t):
    if not edges:
        return 0 if s == t else -1
    if s == t:
        return 0
    return bfs(n, edges, s, t)
