import heapq

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    def bfs():
        queue = [(-1, s, [])]
        visited = set((0, s))
        while queue:
            _, u, path = heapq.heappop(queue)
            path = path + [u]
            if u == t:
                return len(path), path
            for v, w in graph[u]:
                if w == 0 or (v, w) in edges:
                    if (0, v) not in visited:
                        visited.add((0, v))
                        heapq.heappush(queue, (-1 - w, v, path))

    def get_parents():
        distances, _ = bfs()
        if distances == -1:
            return None
        parents = [-1] * n
        q = [(0, s, [])]
        while q:
            d, u, path = heapq.heappop(q)
            if d != 0:
                path = path + [u]
                if parents[u] is None:
                    parents[u] = path[-2]
                for k, v, w in edges:
                    if k == u and w == d:
                        if (0, v) not in visited:
                            visited.add((0, v))
                            heapq.heappush(q, (d - w, v, path))
                        elif w > d:
                            if (0, v) not in visited:
                                visited.add((0, v))
                                heapq.heappush(q, (d - w, v, path))
        return parents

    parents = get_parents()
    if parents[t] is None:
        return -1
    path_weight = 0
    while t != s:
        i = parents[t]
        if i < 0:
            return -1
        j = (i, t)
        k = next((k for k, v, w in edges if k == i and w < path_weight and v == t), None)
        if k is None:
            path_weight += 1
        else:
            path_weight += k[2]
        t = i
    return path_weight
