        return 0 <= r < rows and 0 <= c < cols

    def neighbors(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            yield (r + dr, c + dc)

    def is_valid_path(path):
        prev = None
        for r, c in path:
            if not in_bounds(r, c) or grid[r][c] == '#':
                return False
            if prev is not None and (r, c) not in neighbors(*prev):
                return False
            prev = r, c
        return True

    path = []
    queue = [(start, [start])]
    visited = {start}

    while queue and not is_valid_path(path):
        (r, c), path = queue.pop(0)
        for nr, nc in neighbors(r, c):
            if (nr, nc) == goal:
                return [start] + [(nr, nc)]
            if (nr, nc) not in visited and is_valid(nr, nc):
                queue.append(((nr, nc), path + [(nr, nc)]))
                visited.add((nr, nc))

