        path = []
        while neighbors:
            x, y = neighbors.pop()
            path.append((x, y))
            for dx, dy, _ in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in path:
                    path.append((nx, ny))
                    neighbors.add((nx, ny))
        return path

