    came_from = {}
    g_score = {(start[0], start[1]): 0}

    while frontier:
        current = min(frontier, key=lambda x: list(x) + [g_score[x]])
        if current == goal:
            return get_path([current])
        frontier.remove(current)
        for dx, dy, direction in zip(directions, directions_names):
            x, y = current[0] + dx, current[1] + dy
            if is_valid(x, y):
                tentative_g_score = g_score[current] + 1
                if (x, y) not in g_score or tentative_g_score < g_score[(x, y)]:
                    came_from[(x, y)] = current
                    g_score[(x, y)] = tentative_g_score
                    frontier.add((x, y))
            else:
                print(f"Cannot move {direction} from {current}")

    return []
