    """Util function to unpack pairs while iterating."""
    return next(((y, x) for x, y in f), (None, None))

def dijkstra(graph: list[list[tuple]], start: int) -> list[int]:
    """Dijkstra's implementation to find shortest path from start to all other nodes."""
    n = len(graph)
    inf = float('inf')
    dist = [inf] * n
    pile = [(0, start)]

    while pile:
        d, u = heapq.heappop(pile)
        if dist[u] != inf:
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pile, (dist[v], v))

    return dist

def solve(n: int, edges: list[tuple], s: int, t: int) -> int:
    """Find the length of the shortest path from node s to node t in a directed weighted graph."""
    if s == t:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = dijkstra(graph, s)

    if dist[t] == float('inf'):
        return -1

    return dist[t]
