INF = 1e9

def dijkstra(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distance = [INF] * n
    distance[s] = 0
    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)
        if distance[u] < d:
            pass
        else:
            for v, w in graph[u]:
                if distance[v] > distance[u] + w:
                    distance[v] = distance[u] + w
                    heapq.heappush(pq, (distance[v], v))

    return distance[t] if distance[t] != INF else -1

def solve(n, edges, s, t):
    s = dijkstra(n, edges, s, t)
    if s == -1:
        return t
    t = dijkstra(n, edges, t, s)
    s = dijkstra(n, edges, s, t)
    return -1 if s == -1 else s + t

def find_path(n, edges, s, t):
    visited = set()
    stack = [s]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == t:
                break
            for u, v, w in edges:
                if u == node:
                    heapq.heappush(stack, (w, v))
    return -1 if node != t else sum(w for w, v in stack)

def solve2(n, edges, s, t):
    negative_weight_cycle = find_path(n, edges, s, t)
    if negative_weight_cycle != -1:
        return -1
    return dijkstra(n, edges, s, t)

def bellman_ford(n, edges, s):
    distance = [INF] * n
    distance[s] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if distance[v] > distance[u] + w:
                distance[v] = distance[u] + w
    return distance

def has_negative_weight_cycle(n, edges, s):
    distance = bellman_ford(n, edges, s)
    for u, v, w in edges:
        if distance[v] > distance[u] + w:
            return True
    return False

def solve3(n, edges, s, t):
    if has_negative_weight_cycle(n, edges, s):
        return -1
    return dijkstra(n, edges, s, t)
