            self.index = index
            self.weight = weight

        def __lt__(self, other):
            return self.weight < other.weight

        def __eq__(self, other):
            return self.weight == other.weight

        def __gt__(self, other):
            return self.weight > other.weight

        def __ge__(self, other):
            return not self < other

        def __le__(self, other):
            return not self > other

    pq = [Node(s, 0)]
    visited = set()
    while pq:
        u = pq[0].index
        if u == t:
            return pq[0].weight
        if u in visited:
            heapq.heappop(pq)
            while pq and pq[0].index == u:
                heapq.heappop(pq)
            if not pq:
                return -1
        visited.add(u)
        for v, w in graph[u]:
            if v not in visited:
                heapq.heappush(pq, Node(v, pq[0].weight + w))
    return -1

def solve(n, edges, s, t):
    if s == t:
        return 0
    return dijkstra(edges, n, s, t)
