        if dist[u] < _dist:
            # Dijkstra's guarantees node up to date, skip this iteration
            break
        if u == t:
            return dist[t]
        for v, w in adj_list[u]:
            alt = dist[u] + w
            if alt < dist[v]:
                dist[v] = alt
                heappush(heap, (dist[v], v))

    return -1

def heappush(heap, item):
    heap.append(item)
    _siftdown(heap, 0, len(heap) - 1)

def heappop(heap):
    _siftup(heap, 0)
    result = heap[0]
    heap[0] = heap[-1]
    del heap[-1]
    _siftdown(heap, 0, len(heap) - 1)
    return result

def _siftdown(heap, start_idx, end_idx):
    while start_idx < end_idx:
        parent_idx = (start_idx - 1) >> 1
        if parent_idx < 0 or heap[parent_idx][0] <= heap[start_idx][0]:
            break
        heap[parent_idx], heap[start_idx] = heap[start_idx], heap[parent_idx]
        start_idx = parent_idx

def _siftup(heap, start_idx):
    end_idx = len(heap)
    while True:
        child_idx = (start_idx + 1) << 1
        if child_idx >= end_idx:
            break
        if child_idx + 1 < end_idx and heap[child_idx+1][0] < heap[child_idx][0]:
            child_idx += 1
        if heap[start_idx][0] <= heap[child_idx][0]:
            break
        heap[start_idx], heap[child_idx] = heap[child_idx], heap[start_idx]
        start_idx = child_idx
