def get_direction(r1, r2, neighbors):
    if r1[0] > r2[0] and r2[0] > 0: return (0, -1)
    if r1[0] < r2[0] and r2[0] < (len(neighbors[1])): return (0, 1)
    if r1[1] > r2[1] and r2[1] > 0: return (1, 0)
