from collections import deque

def solve(grid, start, goal):
    def valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def neighbours(x, y):
        return [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#':
        return []
    if grid[goal[0]][goal[1]] == '#':
        return []

    queue = deque([start])
    visited = set([start])
    while queue:  # BFS
        x, y = queue.popleft()
        if (x, y) == goal:
            path = [start]
            while (x, y) != start:
                path.append((x, y))
                next_neighbours = [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]
                for dx, dy in next_neighbours:
                    if (dx, dy) == (x, y):
                        continue
                    if (dx, dy) in visited:
                        continue
                    if not valid(dx, dy):
                        continue
                    path.append((dx, dy))
                    queue.append((dx, dy))
                    visited.add((dx, dy))
                    break
            return path[::-1]  # reverse
        for dx, dy in neighbours(x, y):
            if valid(dx, dy) and (dx, dy) not in visited:
                visited.add((dx, dy))
                queue.append((dx, dy))

    return []
