        curr_dist, u = heapq.heappop(pq)
        if u == t:
            return curr_dist, parents
        if curr_dist > dist[u]:
            logging.warning(f"Dijkstraﾕs algorithm failed; cycle detected.")
            return -1, parents

        for v, w in adj_list[u]:
            alt = curr_dist + w
            if alt < dist[v]:
                dist[v] = alt
                parents[v] = u
                heapq.heappush(pq, (alt, v))

    return -1, parents

