import heapq as h

def solve(n, edges, s, t):
    def find(u, parents):
        if u == t:
            path = []
            while u != s:
                path.append((u, weights[u]))
                u = parents[u]
            path.append((s, 0))
            return sum(way[u] for u, way in reversed(path))
        v = None
        for vj, vi, _ in edges:
            if vj == u:
                for jq, jv, _ in edges:
                    if jv == vj:
                        heapq.heappush(pq, (weights[jv] + weights[u], jv, u))
                v = vi
                break
        parents[u] = v
        for jq, jv, _ in edges:
            if jv == v:
                weights[jv] = min(weights.get(jv, float('inf')), weights[v] + jq)
                if jv not in parents:
                    yield from find(jv, parents)
        if v is not None:
            del weights[v]

    parents = [None] * n
    weights = {u: float('inf') for u in range(n)}
    weights[s] = 0
    pq = [(0, s, s)]
    while pq:
        weight, u, parent = h.heappop(pq)
        for uj, uv, uw in edges:
            if uj == u and (uv not in parents or weights[uv] > weight + uw):
                weights[uv] = weight + uw
                heapq.heappush(pq, (weight + uw, uv, u))
        weights[u] = 0
        yield from find(u, parents)  # discard the yield value but run the generator

    return 0 if t == s else (weights[t] if t in weights else -1)
