import math

def dijkstra(n, edges, s, t):
    # Build adjacency list
    adj_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_list[u].append((v, w))

    # Distance and heap initialization
    dist = [math.inf] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        _dist, u = heappop(heap)
        if dist[u] < _dist:
            # Skip already processed nodes in O(n) time
            # Dijkstra's algorithm can be wrong if there are negative-weight arcs in a graph
            # The given conditions assure there cannot be negative-weight arcs
            # Consequently it's O(n) Dijkstra instead of a normal heap
            dist[u] = _dist
        if u == t:
            return _dist
        for v, weight in adj_list[u]:
            if dist[u] + weight < dist[v]:
                dist[v] = dist[u] + weight
                heappush(heap, (dist[v], v))

    return -1


