def bfs(n, edges, s, t):
    def add_source(s):
        graph[s] = [(iwt, i) for i, wt in edges if i == s]

    def dijkstra(graph, s):
        queue = deque([(0, s)])
        visited = [False] * n
        distances = [sys.maxsize] * n
        distances[s] = 0
        while queue:
            d, u = queue.popleft()
            if visited[u]:
                if d < distances[u]:
                    distances[u] = d
                    for to, wt in reversed(graph[u]):
                        queue.append((d + wt, to))
            elif not visited[u]:
                visited[u] = True
                for to, wt in reversed(graph[u]):
                    queue.append((d + wt, to))
        return distances

