    add_source(s)
    adj_rows = {}
    for u, v, w in edges:
        if u not in adj_rows:
            adj_rows[u] = []
        adj_rows[u].append((v, w))
    for u in adj_rows:
        if u != s:
            graph[u] = [(w, v) for v, w in adj_rows[u]]
            for to, wt in edges:
                if to == u and wt != 0:
                    for v, w in adj_rows[u]:
                        graph[u].append((w + wt, v))

